bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
for i in $(seq 1 24);do
  current="$(docker inspect -f '{{.Image}}' "$name" 2>/dev/null || true)"
  approved="$(docker image inspect -f '{{.Id}}' create-videobot:native-sticker-42fad7 2>/dev/null || true)"
  if test -n "$approved" && test "$current" = "$approved" &&
     test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true &&
     docker logs --tail 160 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' &&
     docker logs --tail 160 "$name" 2>&1 | grep -q '^CREATOR_GATE_PUBLIC_RELEASE=CONNECTED$';then
    break
  fi
  sleep 5
done
current="$(docker inspect -f '{{.Image}}' "$name" 2>/dev/null || true)"
approved="$(docker image inspect -f '{{.Id}}' create-videobot:native-sticker-42fad7 2>/dev/null || true)"
test -n "$approved" && test "$current" = "$approved" || { echo STK_NATIVE_APPROVED_IMAGE_NOT_RUNNING; exit 81; }
docker logs --tail 160 "$name" 2>&1 | grep -q '^CREATOR_GATE_PUBLIC_RELEASE=CONNECTED$' || { echo STK_NATIVE_OWNER_NOT_CONNECTED; exit 82; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createTelegramVideoFetcher} from './src/telegram/telegramFileFetch.mjs';
import {createPostgresStickerSales} from './src/stickers/pgStickerSales.mjs';
import {createPostgresStickerTopicPosts} from './src/stickers/pgStickerTopicPosts.mjs';
import {createStickerPaidCover} from './src/stickers/stickerPaidCover.mjs';
import {createStickerTopicPublisher} from './src/stickers/topicPublication.mjs';
import {createGateOwner} from './owner/gateOwner.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env,pid='sp_76f23430d1c29ca355960a95';
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:2,connectionTimeoutMillis:5000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const sql=await pool.query("SELECT p.product_id,p.seller_user_id,p.price_stars,p.status,t.status AS topic_status,t.telegram_message_id FROM videobot_sticker_products p LEFT JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[pid]);
 if(sql.rowCount!==1||sql.rows[0].status!=='published'||
    Number(sql.rows[0].price_stars)!==50)
   throw Error('STK_NATIVE_MASTER_PRODUCT_NOT_VERIFIED');
 if(sql.rows[0].topic_status&&sql.rows[0].topic_status!=='sent')
   throw Error('STK_NATIVE_UNCERTAIN_EXISTING_TOPIC_RECEIPT');
 const seller=Number(sql.rows[0].seller_user_id);
 if(!Number.isSafeInteger(seller)||seller<=0)
   throw Error('STK_NATIVE_SELLER_INVALID');
 const botToken=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token:botToken,fetchImpl:outgoing.fetch,timeoutMs:25000});
 const gate=await createGateOwner({telegramApi:api,pool});
 const publisher=createStickerTopicPublisher({
   telegramApi:api,getVerifiedStickerTopic:gate.getVerifiedStickerTopic,
   verifyMembership:gate.verifyMembership,verifyReview:gate.verifyStickerReview,
   verifyRelease:gate.verifyRelease,
   receiptStore:createPostgresStickerTopicPosts(pool),
   salesStore:createPostgresStickerSales(pool),
   createPaidCover:createStickerPaidCover({fetchSource:createTelegramVideoFetcher({
      telegramApi:api,token:botToken,fetchImpl:outgoing.fetch})})
 });
 const sent=await publisher.publish({sellerId:seller,productId:pid});
 if(sent?.posted!==true||sent.chatId!==-1002373696859||
    !Number.isSafeInteger(sent.messageId)||sent.messageId<=0)
   throw Error('STK_NATIVE_PUBLICATION_NOT_ACKNOWLEDGED');
 const post=await pool.query("SELECT status,chat_id,message_thread_id,telegram_message_id FROM videobot_sticker_topic_posts WHERE product_id=$1",[pid]);
 if(post.rowCount!==1||post.rows[0].status!=='sent'||
   Number(post.rows[0].chat_id)!==-1002373696859||
   Number(post.rows[0].message_thread_id)!==4640||
   Number(post.rows[0].telegram_message_id)!==sent.messageId)
    throw Error('STK_NATIVE_TOPIC_RECEIPT_INVALID');
 process.stdout.write('STK_NATIVE_STARS_LOCKED_STICKER_IMAGE_PUBLISHED=PASS\n');
 process.stdout.write('STK_NATIVE_TOPIC_DB_READBACK=PASS\n');
 process.stdout.write('STK_NATIVE_POST_REUSED='+String(sent.alreadySent===true)+'\n');
 process.stdout.write('STK_NATIVE_MESSAGE_ID='+sent.messageId+'\n');
 process.stdout.write('STK_NATIVE_STICKER_BUYER_PAYWALL_READY=PASS\n');
}finally{await outgoing.close();await pool.end();}
NODE
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 83
echo STK_NATIVE_SINGLE_BOT_HEALTH=PASS
